(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sq"] = {"ui":{"skip":"Kalo te përmbajtja","back":"← Kthehu te AI-gile","lang.button":"Gjuha: {name}","lang.dialog":"Zgjidh një gjuhë","lang.search":"Kërko gjuhë","lang.none":"Asnjë gjuhë nuk përputhet","lang.notYet":"{name} nuk është përkthyer ende","theme.aria":"Ndrysho temën: e çelët, e errët ose e zezë","theme.toLight":"Kalo te tema e çelët","theme.toDark":"Kalo te tema e errët","theme.toBlack":"Kalo te tema e zezë (e zezë e vërtetë, e butë për ekranet OLED)","words.underline":"Nënvizo këto fjalë në faqe","words.underlineHelp":"Kalo miun mbi një fjalë me pika ose preke, për të parë çfarë do të thotë.","index.title":"AI-gile: ekipi yt AI i zhvillimit, në një tabelë","index.description":"AI-gile është një tabelë kanban për ekipet e programimit me AI. Ata punojnë ndërsa ti fle; ti merr një grumbull të shkurtër gjërash për t'i vendosur, provuar dhe pranuar.","hero.logoAlt":"Ikona e tabelës AI-gile","hero.h1.html":"Ekipi yt AI i zhvillimit, në një&nbsp;tabelë.","hero.alpha":"🐣 Para-alfa e mbyllur","hero.alphaTitle":"E hershme dhe e papërfunduar: faleminderit që e provon!","hero.lede":"Ata ndërtojnë ndërsa ti fle. Zgjohesh me një grumbull të shkurtër: disa pyetje, disa gjëra për t'u provuar, një ose dy diamante vjollcë. Kliko, prano dhe kthehu te kafja.","dl.windows":"Aplikacioni për Windows","dl.browser":"Hape në shfletues","dl.messenger":"📱 Messenger për telefonin tënd","dl.soon":"Së shpejti","dl.notify":"🔔 Më njofto kur hapet","dl.notifySmall":"Alfa ose beta","hero.secondary":"Agjile, por ekipi nuk ka kurrë nevojë për kafen e mbledhjes së shkurtër. (Mbledhjet i bëjnë gjithsesi.)","pitch.h2":"AI-gile me sa fjalë të duash","pitch.lede":"Zgjidh një gjatësi, nga një fjalë deri në 144. Çdo gjatësi është përshkrim më vete, shkruar posaçërisht për të. Tërhiq rrëshqitësin ose përdor shigjetat.","pitch.rangeLabel":"Gjatësia në fjalë","pitch.dice":"🎲 version tjetër","pitch.words.one":"{n} fjalë","pitch.words.other":"{n} fjalë","pitch.letters.one":"{n} shkronjë","pitch.letters.other":"{n} shkronja","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karaktere","count.line.html.one":"{n} kartë është tani në tabelë","count.line.html.other":"{n} karta janë tani në tabelë","people.humans.html.one":"👥 {n} njeri","people.humans.html.other":"👥 {n} njerëz","people.agents.html.one":"🤖 {n} agjent","people.agents.html.other":"🤖 {n} agjentë","people.working.html.one":"⚡ {n} në punë tani","people.working.html.other":"⚡ {n} në punë tani","pre.title":"AI-gile: diçka po ndërtohet","pre.description":"Këtu po ndërtohet diçka: një tabelë ku ekipe AI ndërtojnë atë që kërkon dhe të mësojnë gjatë rrugës. Për tani, para-alfa e mbyllur me miq.","pre.h1":"Këtu po ndërtohet diçka. 🤫","pre.line":"Një tabelë ku ekipe AI ndërtojnë atë që kërkon dhe të mësojnë gjatë rrugës. Për tani, para-alfa e mbyllur me miq.","pre.btn":"🔔 Më njofto kur hapet","pre.peek":"Pas xhamit: tabela e vërtetë, drejtpërdrejt. Çdo kartë është një shirit me ngjyrë.","pre.peekFake":"Pas xhamit: kështu duket një tabelë në punë.","features.aria":"Çfarë bën","f.pile.h":"Një grumbull për ty","f.pile.html":"<b>Për ty</b> mbledh gjithçka që të pret, nga të gjitha projektet: pyetje, gjëra për t'u provuar, detyra që i bën vetëm një njeri. Radha jote të tregon çfarë vjen më pas dhe sa zgjat.","f.sleep.h":"Ekipe që punojnë ndërsa ti fle","f.sleep.p":"Çdo projekt ka një drejtues dhe një ekip agjentësh AI. Shkruaj një koment te karta dhe ekipi zgjohet, bën punën dhe ta kthen me hapa që i ndjek edhe një njeri i lodhur.","f.tester.h":"Fillimisht kontrollon një testues AI","f.tester.p":"Para se të të vijë diçka, testuesi ndjek hapat në një kopje të aplikacionit dhe tregon çfarë pa, me një pamje ekrani. Shfletoji ato që kaluan dhe prano me një klik.","f.proof.h":"Prova, jo premtime","f.proof.p":"Çdo dorëzim tregon çfarë ndryshoi: skedarët, ndryshimet, pamjet e ekranit. S'ke nevojë të hapësh çdo aplikacion për të parë nëse u krye.","f.chat.h":"Bisedo me drejtuesit e tu","f.chat.p":"Një shirit si në Discord: një ikonë për projekt, diamante vjollcë për atë që të do ty. Shkruaji drejtuesit një ide; ai e kthen në karta dhe plan, me një buton ✅ Shko.","f.tidy.h":"E mban vetë rendin","f.tidy.p":"Kartat e ngjashme bashkohen, titujt e ngatërruar rregullohen dhe një kontroll tokenësh e mban kodin të hollë. Më pak gjëra për të ndërruar, më pak për të menduar.","f.private.h":"I yti, në kompjuterin tënd","f.private.li1":"Tabela punon në kompjuterin tënd dhe i përgjigjet vetëm ty.","f.private.li2":"Mesazhet private mes njerëzve janë të enkriptuara nga skaji në skaj.","f.private.li3":"Pa llogari, pa gjurmues, pa cookies.","f.lang.h":"Në gjuhën tënde","f.lang.p":"Mbi 120 gjuhë, nga holandishtja, uellsishtja dhe japonishtja te piratët, Yoda dhe klingonishtja, me kalim të shpejtë në anglisht për termat profesionalë.","f.service.h":"Nga një ide te një shërbim i vërtetë","f.service.p":"Ndërtove diçka me AI që njerëzit tani e përdorin? Shënoje si shërbim dhe tabela të ndihmon ta mbash mirë: kontrolle funksionimi, një faqe publike statusi, incidente me analizë, ndryshime që kanë nevojë për një Go, kopje rezervë të kontrolluara çdo ditë. Ndihma të mëson çdo hap ndërsa ecën.","msgr.h2":"AI-gile Messenger: ekipi yt në xhep","msgr.p1":"Fol me ekipin tënd AI pa hapur tabelën. Bisedo me drejtuesit e projekteve dhe me miqtë, shiko hapat e testimit të një karte dhe përgjigju, të gjitha nga telefoni.","msgr.p2":"Për ta lidhur, skano një kod QR në tabelën tënde. Herën e parë? Një bisedë demo miqësore të tregon si funksionon.","msgr.when":"Fillimisht Android, pastaj një version web për telefona dhe iPhone.","msgr.who":"Drejtuesi yt i projektit","msgr.b1":"Rregullimi i modalitetit të errët është gati. Do hapat e testimit?","msgr.b2":"Po, të lutem!","msgr.b3":"1. Hap Cilësimet. 2. Zgjidh I errët. Duket mirë?","tl.aria":"Kronologjia nga biseda e parë te plani","tl.h2":"Nga biseda e parë te ajo që vjen më pas","tl.lede":"Data dhe orë të vërteta, në zonën tënde kohore. Pas sot është plan, pa data të premtuara.","tl.today":"Sot","tl.planned":"e planifikuar","tl.cards.one":"{n} kartë","tl.cards.other":"{n} karta","join.h2":"Bashkohu","join.lede":"AI-gile po ndërtohet nga një tip i çuditshëm me mjekër, me AuDHD dhe disa beteja me shëndetin mendor, dhe nga shumë agjentë të durueshëm. Tani për tani është private, në alfa të mbyllur me miq. Do ta provosh kur të hapet?","join.btn":"Shpreh interes","join.small":"Do të shkruajmë me email, asgjë tjetër","footer.tag":"AI-gile. Pa gjurmues, pa cookies, pa kafe mbledhjeje.","footer.licence":"Licenca e biznesit","footer.status":"Gjendja","footer.privacy":"Çfarë ruajmë","footer.thanks":"Thirrjet falë ChilledChat","form.sending":"Po dërgohet…","form.failed":"Nuk funksionoi: provo përsëri më vonë.","form.offline":"Nuk u arrit AI-gile: provo përsëri më vonë.","form.keep":"E përdorim vetëm për të të kthyer përgjigje, pastaj e fshijmë. Pa gjurmues, pa cookies.","form.keepLink":"Çfarë ruajmë","interest.title":"AI-gile: më njofto kur hapet alfa","interest.description":"Lër emailin për të mësuar kur hapet alfa ose beta e mbyllur e AI-gile.","interest.h1":"🔔 Më njofto kur hapet","interest.lede":"AI-gile është në para-alfa të mbyllur. Lër emailin dhe do të të shkruajmë një herë, kur të ketë vend për ty.","interest.email":"Emaili yt","interest.which":"Cili test?","interest.alpha":"Alfa e mbyllur: e hershme, e ashpër, plot ndryshime","interest.beta":"Beta: më e qëndrueshme, më vonë","interest.both":"Cilado, cila të vijë e para","interest.submit":"Më shto në listë","interest.thanks":"Faleminderit! Je në listë.","licence.title":"AI-gile: licenca e biznesit","licence.description":"E përdor AI-gile në biznesin tënd? Apliko për një licencë biznesi falas.","licence.h1":"📜 Licenca e biznesit","licence.lede":"E përdor AI-gile në punë? Na trego kush je dhe çfarë bën. Nëse sjell diçka të mirë, licenca është falas.","licence.company":"Kompania","licence.website":"Faqja e internetit","licence.what":"Çfarë bën","licence.how":"Si ndihmon botën","licence.email":"Emaili","licence.submit":"Apliko","licence.thanks":"Faleminderit! Do të përgjigjemi me email.","status.title":"Gjendja e AI-gile","status.h1":"Gjendja e AI-gile","status.quiet":"Gjithçka e qetë","status.intro":"A po funksionon AI-gile tani? Kjo faqe kontrollon çdo 5 minuta faqen e internetit, ndarjen e tabelave, thirrjet dhe shkarkimin.","status.up":"Funksionon (u përgjigj për {ms} ms)","status.slow":"Nuk u përgjigj në kontrollin e fundit, po provoj përsëri","status.down":"Nuk funksionon: nuk u përgjigj në dy kontrollet e fundit","status.svc.web":"Faqja e internetit","status.svc.web.offers":"Kjo faqe: çfarë është AI-gile dhe formulari i interesit","status.svc.boards":"Ndarja e tabelave","status.svc.boards.offers":"Tabela publike, mesazhe mes miqve dhe ftesa","status.svc.calls":"Thirrjet","status.svc.calls.offers":"Zë, video dhe ndarje ekrani në AI-gile","status.svc.download":"Shkarkimi","status.svc.download.offers":"Instaluesi për Windows dhe lidhjet e ftesave","status.checking":"Po kontrollohet…","status.offline":"Shërbimi i gjendjes nuk arrihet tani (po provoj përsëri)","status.updated":"përditësuar {ago}","status.justNow":"tani fill","status.min":"{n} min më parë","status.hours":"{n} orë më parë","status.days":"{n} ditë më parë","privacy.title":"AI-gile: çfarë ruajmë","privacy.h1":"Çfarë ruajmë","privacy.lede":"Shkurt: vetëm atë që na dërgon, dhe jo për shumë kohë.","privacy.only":"Vetëm atë që na dërgon: atë që shkruan në një formular, si emailin tënd. Asgjë tjetër për ty.","privacy.sealed":"Vuloset që serveri ynë të mos e lexojë dot: në shfletuesin tënd para se të niset (në një shfletues më të vjetër, sapo mbërrin). Vetëm tabela jonë mund ta hapë.","privacy.server":"Fshihet nga serveri sapo arrin në tabelën tonë. Çdo gjë që mbetet aty pas 30 ditësh fshihet gjithsesi.","privacy.board":"E mbajmë në tabelën tonë vetëm derisa të të përgjigjemi, pastaj e fshijmë edhe aty.","privacy.none":"Pa gjurmues, pa cookies, pa analitikë.","privacy.local":"Gjuha jote dhe zgjedhja mes temës së çelët dhe të errët mbeten në shfletuesin tënd. Nuk na dërgohen kurrë.","privacy.ask":"Do që të zhduket më herët? Përgjigju emailit tonë dhe na e thuaj.","live.h2":"Shikoje duke u ndërtuar, drejtpërdrejt","live.caption":"Çdo kartë është e fshehur: sheh formën e punës, jo fjalët.","live.watching.one":"drejtpërdrejt: {n} po shikon","live.watching.other":"drejtpërdrejt: {n} po shikojnë","live.last.now":"Karta e fundit u zhvendos pak më parë","live.last.min.one":"Karta e fundit u zhvendos {n} minutë më parë","live.last.min.other":"Karta e fundit u zhvendos {n} minuta më parë","live.last.hour.one":"Karta e fundit u zhvendos {n} orë më parë","live.last.hour.other":"Karta e fundit u zhvendos {n} orë më parë","live.last.day.one":"Karta e fundit u zhvendos {n} ditë më parë","live.last.day.other":"Karta e fundit u zhvendos {n} ditë më parë","live.offline":"Tabela drejtpërdrejt po merr pak pushim. Kthehu së shpejti.","live.cols":"Backlog|Për t'u bërë|Në punë|Ekipi po kontrollon|Për ty ta testosh|Për ekipin|Kryer"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotë.","Deleguar."]},{"n":2,"texts":["Kanban robotësh.","Agjentët punojnë.","Idetë ndërtohen."]},{"n":3,"texts":["Kanban për robotë.","Idetë bëhen funksione.","Kanban falas agjentësh."]},{"n":5,"texts":["Tabelë kanban e drejtuar nga agjentë.","Ti shkruan karta. Agjentët ndërtojnë.","Falas, lokale, testuar, pak çudi."]},{"n":8,"texts":["Një tabelë kanban falas ku punojnë agjentë AI.","Shkruaj një ide. Agjentët e ndërtojnë. Ti e pranon.","Agjilitet për një njeri dhe shumë robotë të durueshëm."]},{"n":13,"texts":["Një tabelë kanban në kompjuterin tënd ku kartat i marrin agjentët AI e punojnë.","Shkruaj një ide. Një ekip agjentësh e ndërton. Një testues e kontrollon. Ti thua po.","Falas, pa llogari e pa gjurmues: një tabelë, disa robotë dhe ti ke fjalën."]},{"n":21,"texts":["AI-gile është një tabelë kanban për të punuar me agjentë AI që programojnë. Ata marrin kartat; ti i teston dhe i pranon.","Çdo projekt ka një drejtues dhe një ekip agjentësh AI. Shkruaj koment te çdo kartë dhe ekipi nis punën.","Një tabelë personale detyrash, falas, që punon në kompjuterin tënd. Punëtorët janë robotë. Ai që thotë po je ti."]},{"n":34,"texts":["Ti vë idetë në tabelë. Një ekip agjentësh AI i kthen në funksione që punojnë, i teston dhe ta kthen me hapa për t'i provuar. Asgjë nuk quhet e kryer derisa ta thuash ti.","AI-gile është një tabelë kanban e bërë në shtëpi, që Rich e ndërtoi me shumë ndihmë nga agjentët që tani i drejton vetë. Është falas, punon në kompjuterin tënd dhe ndahet me miqtë, nuk shitet.","Imagjino një tabelë kanban të zakonshme, me kolona nga Backlog te Kryer, vetëm se kartat i marrin agjentë AI. Raportojnë përparimin, pyesin kur ngecin dhe gjithmonë presin miratimin tënd."]},{"n":55,"texts":["AI-gile është një tabelë kanban ku ekipi përbëhet nga agjentë AI. Çdo projekt ka një drejtues që planifikon punën dhe ndihmës që e ndërtojnë. Kur një funksion është gati, një testues AI e provon dhe merr një pamje ekrani, pastaj ai bie në grumbullin tënd. Pranoje, ose shkruaj koment dhe ata e ripunojnë.","Nisi si mënyra e një njeriu për të ndjekur shumë seanca programimi me AI njëkohësisht, dhe u rrit në një tabelë të vërtetë. Punon në kompjuterin tënd, nuk kërkon llogari dhe nuk ka gjurmues. Është falas për miqtë dhe të kureshtarët. Është edhe e papërfunduar, ndaj prit skaje të ashpra dhe ndonjë befasi.","Ja versioni i sinqertë. Idetë duhet t'i kesh prapë ti, dhe rezultatet duhet t'i kontrollosh prapë ti. AI-gile bën gjithçka në mes: i mban kartat në rregull, zgjon agjentin e duhur kur komenton, tregon saktësisht çfarë ndryshoi dhe i vë të gjitha në një grumbull të shkurtër për ty."]},{"n":89,"texts":["AI-gile është një tabelë kanban falas që e ekzekuton në kompjuterin tënd. Në vend të njerëzve, çdo projekt ka një ekip agjentësh AI: një drejtues që idetë e tua i kthen në karta dhe plan, dhe ndihmës që i marrin kartat sipas përparësisë. Kur diçka është ndërtuar, një testues AI ndjek hapat e testit dhe të tregon çfarë pa. Pastaj pret në një grumbull me emrin Për ty. Ti e pranon, ose komenton dhe ekipi provon përsëri. Asgjë nuk arrin te Kryer pa ty.","Disa gjëra që mund të mos i presësh. Një roje nate e mbush kolonën Për t'u bërë ndërsa ti fle, duke zgjedhur karta që nuk kanë nevojë për përgjigje nga ti. Një numërues tokenësh tregon sa kanë përdorur agjentët sot dhe këtë javë, dhe Modaliteti pa tokenë u thotë të ndalojnë shpenzimin. Mund t'u shkruash miqve, dhe mesazhet private janë të enkriptuara nga skaji në skaj. Tabela flet rreth 120 gjuhë, përfshirë holandisht, flamandisht, piratësh dhe klingonisht. Asgjë nga kjo nuk kushton asnjë qindarkë, dhe askush nuk po përpiqet të ta shesë.","AI-gile është një projekt i vogël personal, jo kompani. Rich donte të kujdesej për disa projekte programimi me AI pa hapur çdo aplikacion për t'i kontrolluar, ndaj ai dhe agjentët ndërtuan një tabelë për këtë, pastaj me të ndërtuan pjesën tjetër të saj. Është në para-alfa të mbyllur, që do të thotë se punon, më së shumti, për një grusht miqsh. Nuk ka faqe çmimesh, buletin dhe as plan rritjeje. Nëse të duket e dobishme, mund të kërkosh ta provosh kur të hapet pak më shumë."]},{"n":144,"texts":["AI-gile është një tabelë kanban për një njeri dhe shumë agjentë AI. Punon në kompjuterin tënd dhe është plotësisht falas. Shton projekte dhe secili merr një drejtues dhe një ekip të vogël. Bisedon me drejtuesin, pak si në Discord, dhe përshkruan një ide; drejtuesi e kthen në karta dhe plan, pastaj pret që ti të shtypësh Shko. Ekipi i kalon kartat sipas përparësisë, me një rresht komandash të thjeshtë të bërë për modelet gjuhësore. Para se diçka të të kthehet, një testues AI ndjek hapat në një kopje të aplikacionit dhe bashkëngjit një pamje ekrani. Puna e përfunduar bie në grumbullin tënd me skedarët e ndryshuar dhe ndryshimet. Ti e pranon, ose lë një koment dhe ekipi zgjohet e provon përsëri. Vetëm ti mund ta kalosh një kartë te Kryer.","Një ditë me AI-gile, përafërsisht. Në mbrëmje lë disa komente: ky buton është në vendin e gabuar, ajo listë duhet renditur, mund të kemi një temë të errët. Shkon të flesh. Agjentët i lexojnë komentet, bëjnë ndryshimet, i testojnë dhe ta kthejnë punën. Nëse Për t'u bërë mbaron, roja e natës e mbush nga backlog me karta që nuk kanë nevojë për përgjigje nga ti. Në mëngjes ka një grumbull të shkurtër: disa pyetje dhe disa gjëra për t'u provuar, secila me hapa që i ndjek edhe një njeri i përgjumur dhe me një pamje ekrani që punon. I kalon një nga një, pranon të mirat dhe kthen të tjerat. Numëruesi i tokenëve tregon sa shpenzoi gjithçka, dhe Modaliteti pa tokenë është për javët e pakta. Pastaj ha mëngjes, ku agjentët ende nuk mund të ndihmojnë.","Së pari, çfarë nuk është AI-gile. Nuk është startup, nuk shitet dhe askush nuk mbledh të dhënat e tua. Është një tabelë falas që punon në kompjuterin tënd, pa llogari, pa gjurmues dhe pa cookies. Çfarë është: një vend i rregullt për të parë të gjitha projektet e programimit me AI njëherësh, me një ekip agjentësh që bëjnë kartat dhe ti që merr vendimet. Bashkon kartat e ngjashme, rregullon titujt e ngatërruar dhe vëzhgon që kodi të mbetet i hollë. Flet rreth 120 gjuhë, nga holandishtja dhe flamandishtja te piratët dhe klingonishtja. Miqtë mund t'i shkruajnë njëri-tjetrit privatisht dhe të enkriptuar. E ndërtoi Rich me një numër të madh agjentësh të durueshëm, kryesisht duke përdorur vetveten. Është në para-alfa të mbyllur, ndaj në disa vende është e ashpër. Nëse të tingëllon argëtuese, kërko me mirësi dhe mund të hysh herët."]}],"quips":{"1":"Një fjalë. E guximshme. Ndoshta tepër.","3":"Tri fjalë. Tashmë më të sinqerta se shumica e faqeve të produkteve.","8":"Tetë fjalë. Prapë më të shkurtra se një mbledhje e shkurtër.","21":"Gjatësitë janë story points, meqë ra fjala. Natyrisht që janë.","55":"Pesëdhjetë e pesë fjalë. Dy karta u kryen ndërsa lexoje.","144":"Kjo është e gjata. Nuk ka 233. Agjentët kanë shkuar të flenë."}},"timeline":{"first-idea.name":"Ideja e parë","first-idea.line":"Biseda e parë, para se të ekzistonte ndonjë kod.","first-board.name":"Tabela e parë","first-board.line":"Një tabelë që ndjek ndërtimin e vet: karta, kolona, tërhiq e lësho, projekte.","team-roles.name":"Ekipi dhe rolet","team-roles.line":"Profile agjentësh, shabllone ekipesh, hapësira dhe kush bën çfarë.","install.name":"Instalimi dhe versionet","install.line":"Një zip që e instalon edhe një mik, vetëpërditësime, kanale dhe kthim prapa.","usage-saver.name":"Kursimi i përdorimit","usage-saver.line":"Mat sa kushtojnë ekzekutimet, mbaje kodin të hollë, kurse kufirin tënd.","friends.name":"Miqtë dhe ndarja","friends.line":"Mesazhe private, një rele e kodifikuar, ftesa, role dhe projekte të përbashkëta.","languages.name":"Gjuhët","languages.line":"Çdo tekst ekrani në një skedar gjuhe, me holandishten dhe flamandishten të parat.","ai-tester.name":"Testuesi AI","ai-tester.line":"Një testues kontrollon çdo dorëzim i pari dhe tregon çfarë pa.","website.name":"Faqja e internetit","website.line":"aigile.lol, parapamja dhe kjo kronologji.","streaming.name":"Biseda dhe transmetimi","streaming.line":"Discord, Twitch, OBS, modaliteti i transmetuesit, GIF-e dhe emoji.","no-ai.name":"Edicioni pa AI","no-ai.line":"Një tabelë për njerëzit që programojnë pa AI, dhe tabela publike.","night-watch.name":"Roja e natës","night-watch.line":"Një rojtar dhe Scrum Master i mbajnë ekipet në punë ndërsa ti fle.","p-more.name":"Gjithçka tjetër","p-more.line":"Ide më të vogla që presin radhën.","p-android.name":"Telefoni dhe Android","p-android.line":"Arrije tabelën nga telefoni, pastaj një aplikacion Android vendas.","p-release.name":"Alfa e më tej","p-release.line":"Alfa e mbyllur, faqja e gjallë, pastaj beta.","p-languages.name":"Më shumë gjuhë","p-languages.line":"Mbi njëqind gjuhë dhe një mënyrë zhytjeje për ata që mësojnë.","p-engines.name":"Më shumë motorë AI","p-engines.line":"Zgjidh Claude, Codex ose Gemini për çdo agjent.","p-pro.name":"Praktikë profesionale","p-pro.line":"Etiketa rreziku, porta bashkimi, karta incidentesh dhe parapete.","p-self.name":"Kujdesi për ty","p-self.line":"Modaliteti i lodhjes, kujtesa për kujdesin ndaj vetes dhe 4:20.","p-servers.name":"Serverët dhe rritja","p-servers.line":"Cilësime globale serveri, role dhe planifikim për rritje.","p-livestream.name":"Shtesa transmetimi","p-livestream.line":"Biseda e Twitch, emoji të personalizuara dhe një pamje e gjallë publike."},"words":{"button":"📖 Termat profesionalë","h":"📖 Fjalët e shpjeguara","intro":"Fjalët që has në AI-gile, të shpjeguara thjesht: si ndërtohet, si ndryshohet pa rrezik, si mbahet në punë për njerëzit që e përdorin dhe si punohet si ekip me AI.","search":"Kërko një fjalë…","none":"Asnjë fjalë nuk përputhet.","close":"Mbyll","count":{"one":"{count} fjalë","other":"{count} fjalë"},"groups":[{"id":"build","name":"🛠️ Ndërtimi"},{"id":"change","name":"🔀 Ndryshime pa rrezik"},{"id":"run","name":"🛎️ Mbajtja e një shërbimi"},{"id":"team","name":"🤝 Puna në ekip (dhe me AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Dosja e kodit të projektit dhe historiku i plotë i commit-eve të tij, zakonisht i mbajtur edhe në GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Një linjë pune e ndarë në kod, që ndryshimet të bëhen pa prekur versionin kryesor.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Një pamje e ruajtur e kodit, me një shënim të shkurtër për çfarë ndryshoi. Mund të kthehesh gjithmonë te njëra.","also":["commits","commit-e","commit-eve"]},{"id":"push","g":"build","word":"Push","text":"Dërgimi i pamjeve të ruajtura (commit-e) nga ky kompjuter lart në GitHub, që të kenë kopje rezervë dhe të ndahen."},{"id":"merge","g":"build","word":"Merge","text":"Bashkimi i ndryshimeve të një branch-i përsëri në versionin kryesor."},{"id":"pr","g":"build","word":"Pull request","text":"Kërkesa që ndryshimet e një branch-i të kontrollohen dhe të bashkohen në versionin kryesor.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Rregullimi i kodit pa ndryshuar çfarë bën: skedarë më të vegjël, emra më të qartë, më pak përsëritje."},{"id":"bug","g":"build","word":"Bug","text":"Diçka që nuk funksionon siç duhet.","also":["bugs","bug-e","bug-u","bug-et"]},{"id":"test","g":"build","word":"Test","text":"Provimi i një pune të gatshme për të parë nëse bën çfarë u kërkua, para se ta pranosh.","also":["testi","testit","testin","teste","testet","testeve","testim","testimi","testuar","testosh","testesh","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Shkurtim për quality assurance, sigurimi i cilësisë: kontrollet automatike që ekzekutohen para se diçka të dalë live. Kur QA është e kuqe, diçka ka dështuar dhe nuk mund të dalë live derisa të rregullohet.","also":["kontroll cilësie","kontrollet e cilësisë","sigurimi i cilësisë"]},{"id":"deploy","g":"change","word":"Deploy","text":"Vënia në punë e një versioni të ri, për shembull në një server ku e përdorin njerëzit."},{"id":"release","g":"change","word":"Publikim","text":"Një paketë me emër e punës së mbaruar që del live bashkë, me shënime të shkurtra për çfarë ndryshoi. 🚀 Publikimet i shkruajnë shënimet nga kartat e përfunduara.","also":["publikime","publikimet","release"]},{"id":"rollback","g":"change","word":"Kthim mbrapsht","text":"Kthimi te versioni i fundit që punonte, kur një i ri shkakton telashe. Në AI-gile kjo krijon një listë kontrolli me hapat e zhbërjes të shkruar në çdo ndryshim.","also":["rollback","kthe mbrapsht","u kthye mbrapsht"]},{"id":"live","g":"change","word":"Live","text":"Versioni i vërtetë që përdorin njerëzit, ndryshe nga një kopje për të provuar gjëra. Zhvilluesit e quajnë edhe prodhim (production).","also":["prodhim","produksion","production"],"noTip":1},{"id":"change","g":"change","word":"Ndryshim","text":"Një ndryshim i planifikuar te diçka që njerëzit mbështeten, i shkruar më parë: çfarë, pse, rreziku, kur dhe si zhbëhet. Fillo një me 🔀 Ngrit një ndryshim.","also":["ndryshime","kërkesë ndryshimi","kërkesa ndryshimi"],"noTip":1},{"id":"risk","g":"change","word":"Rrezik","text":"Diçka që mund të shkojë keq, e vlerësuar sipas sa e mundshme është dhe sa keq do të ishte. ⚠️ Rreziqe i mban në një listë, pikët më të larta të parat, secili me një datë për ta parë sërish.","also":["rreziqe","regjistri i rreziqeve"]},{"id":"chgwin","g":"change","word":"Dritare ndryshimesh","text":"Oraret kur ndryshimet lejohen të dalin live, si një mbrëmje e qetë të martë. Jashtë dritares një kartë ndryshimi nuk mund të përfundohet, përveç kur është urgjencë.","also":["dritaret e ndryshimeve","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Një votim i shpejtë pak para se një ndryshim të dalë live: secili që duhet ta miratojë thotë Go ose No go. Vazhdohet vetëm kur bien dakord.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Miratim","text":"Pritja për një po para se të fillojë puna. Një kartë që hap një mik, ose një ndryshim, pret te ✅ Miratime derisa ta miratosh ose ta refuzosh.","also":["miratime","mirato"]},{"id":"quiettime","g":"change","word":"Orë qetësie","text":"Një periudhë kohe, si një transmetim, një demo ose nata, kur asgjë nuk del live. Ekipet vazhdojnë të punojnë dhe të testojnë, por dalja live pret derisa të mbarojë. Diku tjetër quhet ngrirje ndryshimesh.","also":["orët e qetësisë","ngrirje ndryshimesh","change freeze"]},{"id":"service","g":"run","word":"Shërbim","text":"Diçka që ke ndërtuar dhe që njerëzit e kanë të nevojshme, si një faqe interneti ose një aplikacion, që kujdesesh të vazhdojë të punojë. Shëno “Ky projekt është një shërbim” dhe shkruaj çfarë ofron, kush e përdor dhe kush është në gatishmëri.","also":["shërbime","shërbimi"]},{"id":"uptime","g":"run","word":"Kontroll funksionimi","text":"Një kontroll automatik, çdo disa minuta, nëse shërbimi yt ende përgjigjet. Nëse dështon disa herë rresht, AI-gile hap vetë një kartë incidenti.","also":["uptime","kontrolle funksionimi","disponueshmëri"]},{"id":"statuspage","g":"run","word":"Faqja e statusit","text":"Një faqe publike që tregon nëse një shërbim punon (jeshile, portokalli ose e kuqe) me lajmin e fundit, që njerëzit që e përdorin ta shohin vetë në vend që të pyesin.","also":["faqe statusi","status page"]},{"id":"incident","g":"run","word":"Incident","text":"Diçka që është prishur pikërisht tani për njerëzit që e përdorin, si kur faqja nuk hapet. Një kartë 🔥 incidenti kalon para radhës: e para është ta vësh sërish në punë.","also":["incidente","incidentet","ndërprerje"]},{"id":"major","g":"run","word":"Incident i madh","text":"Një incident i madh: shumë njerëz të prekur, ose para a të dhëna në rrezik. Një buton i vë të gjitha ekipet mbi të (tufa), zgjon atë që është në gatishmëri dhe kërkon një përditësim statusi çdo 30 minuta.","also":["incidente të mëdha","major incident"]},{"id":"oncall","g":"run","word":"Në gatishmëri","text":"Të jesh ai që përgjigjet kur diçka prishet, edhe natën. Çdo shërbim ka një anëtar ekipi në gatishmëri që zgjohet i pari për incidentet e tij.","also":["gatishmëri","on call","on-call"]},{"id":"replyby","g":"run","word":"Koha e përgjigjes","text":"Sa gjatë mund të presë një kartë për përgjigjen e parë, për shembull një orë për një incident. Pas kësaj merr një orë të kuqe, që asgjë të mos harrohet në heshtje. Quhet edhe objektiv përgjigjeje.","also":["kohët e përgjigjes","objektiv përgjigjeje"]},{"id":"postmortem","g":"run","word":"Analiza pas incidentit","text":"Një vështrim i shkurtër pas një incidenti: çfarë ndodhi, çfarë ndihmoi dhe çfarë duhet ndryshuar, pa fajësuar askënd. Një incident nuk mbyllet pa të. Shpesh quhet edhe post-mortem.","also":["analiza pas incidenteve","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Problem","text":"Shkaku i fshehur pas një ose më shumë incidenteve. Një kartë 🧩 problemi bashkon incidentet që përsëriten, që shkaku të gjendet dhe të rregullohet përgjithmonë.","also":["probleme","problemet"],"noTip":1},{"id":"rootcause","g":"run","word":"Shkaku rrënjësor","text":"Arsyeja e vërtetë pse u prish diçka, jo vetëm ajo që pe të shkonte keq. Rregullo shkakun rrënjësor dhe incidenti nuk kthehet më.","also":["shkaqe rrënjësore","root cause"]},{"id":"workaround","g":"run","word":"Zgjidhje e përkohshme","text":"Një mënyrë për t'i mbajtur gjërat në punë derisa rregullimi i vërtetë të jetë gati, si rinisja e diçkaje kur ngec. Shkruhet në kartën e problemit që askush të mos ketë nevojë ta zbulojë sërish.","also":["zgjidhje të përkohshme","workaround"]},{"id":"knownerror","g":"run","word":"Gabim i njohur","text":"Një problem, shkaku i të cilit dihet dhe që ka një zgjidhje të përkohshme, por nuk është rregulluar ende. 🧩 Gabime të njohura i rendit, që të gjithë të përdorin zgjidhjen e përkohshme në vend që të gërmojnë sërish.","also":["gabime të njohura","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Udhëzime hap pas hapi për të rregulluar një lloj të njohur problemi, që të bëhet njësoj dhe shpejt çdo herë. Pas një incidenti të madh ekipi mund të të propozojë një për ta miratuar.","also":["runbook-e","udhëzues pune"]},{"id":"backup","g":"run","word":"Kopje rezervë","text":"Një kopje e ruajtur e të dhënave të tua nga më parë, për t'u mbështetur nëse diçka humbet ose dëmtohet. AI-gile bën një kopje rezervë të tabelave të tua çdo ditë.","also":["kopje rezervë","backup","bekap"]},{"id":"restore","g":"run","word":"Rikthim","text":"Kthimi i të dhënave nga një kopje rezervë. Një kopje rezervë vlen vërtet vetëm kur e di që mund të rikthehet, ndaj ia vlen ta provosh herë pas here.","also":["rikthe","u rikthye","restore","rivendosje"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ide dhe punë që nuk janë planifikuar ende. Asgjë aty nuk punohet derisa të kalojë te Për t'u bërë."},{"id":"sprint","g":"team","word":"Sprint","text":"Një periudhë e shkurtër pune (shpesh një ose dy javë) me një set kartash të përcaktuara për t'u mbaruar.","also":["sprint-et","sprinti","sprinte","sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Një kontroll i shpejtë: çfarë bëri secili anëtar i ekipit, çfarë bën më pas dhe çfarë e pengon.","also":["standup","stand-up-et","stand-up-e","stand-up-i","stand-up-it","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Një tabelë me kolona (Për t'u bërë, Në punë, Kryer) ku kartat lëvizin nga e majta në të djathtë ndërsa bëhet puna."},{"id":"wip","g":"team","word":"Kufiri WIP","text":"Punë në vazhdim: sa karta më së shumti duhet të mbajë një kolonë, që ekipi t'i mbarojë gjërat para se të nisë të tjera.","also":["WIP"]},{"id":"dod","g":"team","word":"Përkufizimi i Përfunduar","text":"Lista e shkurtër e ekipit për çfarë do të thotë “mbaruar”, si i testuar dhe i shpjeguar, para se një kartë të të dorëzohet. Binjaku i saj, Përkufizimi i Gati, thotë kur një kartë është mjaft e qartë për të filluar.","also":["Definition of Done","Përkufizimi i Gati","Definition of Ready"]},{"id":"testpile","g":"team","word":"Stiva e testeve","text":"Kartat e mbaruara që presin t'i provosh, njëra pas tjetrës. Prano njërën ose ktheje me një shënim, dhe vjen tjetra.","also":["stiva testesh"]},{"id":"retro","g":"team","word":"Retro","text":"Një vështrim pas te mënyra si punon ekipi, për t'u marrë vesh për një gjë që të bëhet më mirë. Në AI-gile një retro propozon një ndryshim në mënyrën e punës së ekipit, dhe ti thua Vazhdo ose Jo ende.","also":["retrospektivë","retrospektiva"]},{"id":"peerreview","g":"team","word":"Rishikim nga kolegët","text":"Një palë sy e dytë: një AI tjetër kontrollon punën e çdo karte para se të arrijë te ti, që të kalojnë më pak gabime.","also":["peer review","rishikim kodi","code review"]},{"id":"swarm","g":"team","word":"Tufa","text":"Të gjithë në punë: çdo ekip lë punën tjetër për të ndihmuar në një projekt urgjent derisa të zgjidhet. Projektet e tjera presin ndërkohë.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Ai që e mban punën në lëvizje: dallon kartat e ngecura, nxit ekipet dhe të kujton çfarë pret. Në AI-gile këtë e bën Lead Scrum Master në të gjitha projektet.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agjent","text":"Një AI që punon vetë në një detyrë: lexon kodin, bën ndryshime, ekzekuton kontrolle dhe raporton.","also":["agjentë","agjenti","agjentit","agjentët","agjentëve","agjentësh","agent","agents"]},{"id":"token","g":"team","word":"Token","text":"Njësia në të cilën numërohet përdorimi i AI: afërsisht disa shkronja teksti të lexuar ose të shkruar. Më pak tokenë, më shumë mbetet nga plani.","also":["tokenë","tokenët","tokenëve","tokens"]},{"id":"hook","g":"team","word":"Grep","text":"Një komandë e vogël që ekzekutohet vetë në një çast të caktuar, p.sh. kur nis një sesion AI, që ekipi t'i dëgjojë komentet e tua.","also":["grepa","grepi","hook","hooks"]}]}};
